referenceSolutions.javascript:
export function solve(object, path, value) {
  const copy = structuredClone(object);
  let current = copy;
  for (let i = 0; i < path.length - 1; i++) {
    current[path[i]] ??= {};
    current = current[path[i]];
  }
  current[path[path.length - 1]] = value;
  return copy;
}

